import{_ as t,a}from"./chunks/description1.C31PqN2a.js";import{c as r,Q as n,j as i,m as o}from"./chunks/framework.DjobWxAB.js";const f=JSON.parse('{"title":"Battery Handling Precautions","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/Safety/battery-handling.md","filePath":"manual/Safety/battery-handling.md","lastUpdated":1779182288000}'),s={name:"manual/Safety/battery-handling.md"};function l(d,e,g,c,h,p){return n(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="battery-handling-precautions" tabindex="-1">Battery Handling Precautions <a class="header-anchor" href="#battery-handling-precautions" aria-label="Permalink to &quot;Battery Handling Precautions&quot;">​</a></h1><p>Safe handling, charging, and storage of the RBQ’s on-board battery. For replacement steps, see <a href="/RBQ/manual/Maintenance/battery.html">Battery Replacement</a>.</p><h2 id="charging" tabindex="-1">Charging <a class="header-anchor" href="#charging" aria-label="Permalink to &quot;Charging&quot;">​</a></h2><figure><img src="'+t+'" alt="Charging with RBQ10 dedicated charger"><img src="'+a+'" alt="Charging with RBQ10 docking station"><figcaption style="text-align:center;">[ Use only the designated charger and docking station. ]</figcaption></figure><div class="custom-block safety-label-block" style="padding:1rem 1.5rem;border-radius:8px;background:rgba(211, 84, 0, 0.12);border-left:4px solid #d35400;display:flex;gap:1rem;align-items:stretch;"><div style="display:flex;align-items:center;justify-content:center;flex-shrink:0;width:2.5rem;"><span style="font-size:2.5rem;line-height:1;color:#d35400;" aria-hidden="true">⚠</span></div><div style="flex:1;"><p class="custom-block-title">CAUTION</p><p>1) Charge only with the RBQ10 dedicated charger or RBQ10 docking station. Other chargers can cause overcharge, overheating, or fire.<br>2) While charging, keep the robot and charger away from flammables and heat sources.<br>3) Do not use damaged chargers or cables.</p></div></div><p>Charging steps are described on the <a href="/RBQ/manual/Operation/charging.html">Charging</a> page.</p><ul><li><strong>Fully discharged</strong>: If the robot is fully discharged and will not power on, the docking station may not charge it. In that case, connect the supplied external charger directly to the charging port.</li></ul><h2 id="handling-and-storage" tabindex="-1">Handling and storage <a class="header-anchor" href="#handling-and-storage" aria-label="Permalink to &quot;Handling and storage&quot;">​</a></h2><ul><li><strong>Impact and penetration</strong>: Do not drop the battery, puncture it, or submerge it. Do not use a damaged battery; contact Rainbow Robotics.</li><li><strong>Temperature</strong>: Stay within the specified storage and use temperature range. Do not expose to high heat, direct sunlight, or heaters.</li><li><strong>Storage</strong>: Do not store the battery upside down. If unused for a long time, check its condition periodically.</li></ul><div class="custom-block safety-label-block" style="padding:1rem 1.5rem;border-radius:8px;background:rgba(192, 57, 43, 0.12);border-left:4px solid #c0392b;display:flex;gap:1rem;align-items:stretch;"><div style="display:flex;align-items:center;justify-content:center;flex-shrink:0;width:2.5rem;"><span style="font-size:2.5rem;line-height:1;color:#c0392b;" aria-hidden="true">⚠</span></div><div style="flex:1;"><p class="custom-block-title">DANGER</p><p><strong>Battery removal when not in use</strong>: When not in use, <strong>remove the battery</strong> for storage. Leaving the battery installed in a powered-off robot for <strong>more than 24 hours</strong> can cause <strong>irreversible damage</strong>.</p></div></div>',10)])])}const b=r(s,[["render",l]]);export{f as __pageData,b as default};
